// src/LoginPage.js
import React, { useState, useEffect } from "react";
import { fetchUsers, saveUser, sendEmail, UpdateUser } from "./service/APIService"; // Import UpdateUser function
import { Col, Image, Row, Modal, Button } from "react-bootstrap";
import { Link } from "react-router-dom";
import CryptoJS from "crypto-js";
import { FiEye, FiEyeOff } from "react-icons/fi";
import "./styles/LoginPage.css";
import config from "./config.json";
import banner from "./images/banner.jpg";
import ForgotPassword from "./ForgotPassword";
import close from "./images/delete.png";

const SECRET_KEY = process.env.REACT_APP_KEY;

const LoginPage = ({ onLogin }) => {
  const [showRegister, setShowRegister] = useState(false);
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [currentUser, setCurrentUser] = useState({});
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [generatedOtp, setGeneratedOtp] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [isOtpSent, setIsOtpSent] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [biometricEnabled, setBiometricEnabled] = useState(false);
  const [country, setCountry] = useState("");

  useEffect(() => {
    const sessionUser = JSON.parse(localStorage.getItem("loggedInUser"));
    const useremail = localStorage.getItem("loggedInUserEmail");

    if (sessionUser) {
      setEmail(sessionUser.email);
      setName(sessionUser.name);
    } else {
      setEmail(useremail);
    }
    const isBiometricEnabled = localStorage.getItem("biometricEnabled") === "true";
    setBiometricEnabled(isBiometricEnabled);
    //if (isBiometricEnabled) handleBiometricLogin();
  }, []);

  const encryptPassword = (password) => CryptoJS.AES.encrypt(password, SECRET_KEY).toString();
  const decryptPassword = (encryptedPassword) => CryptoJS.AES.decrypt(encryptedPassword, SECRET_KEY).toString(CryptoJS.enc.Utf8);
  const generateOtp = () => Math.floor(100000 + Math.random() * 900000).toString();

  const handleSendOtp = async (e) => {
    console.log({ email, name, password: "encryptedPassword", country });
    e.preventDefault();
    setLoading(true);
    const existingUser = await fetchUsers(email);
    if (existingUser) {
      setError("User already exists with this email");
      setLoading(false);
      return;
    }

    const otpCode = generateOtp();
    setGeneratedOtp(otpCode);
    const htmlContent = `<p>Your OTP code is: ${otpCode}</p>`;
    const emailData = {
      sender: process.env.REACT_APP_SENDEREMAIL,
      recipient: email,
      subject: `${config.apptitle} Registration OTP Code`,
      cc: email,
      body: htmlContent,
    };

    try {
      await sendEmail(emailData);
      setIsOtpSent(true);
      setError("");
    } catch (error) {
      console.error("Failed to send OTP email", error);
      setError("Failed to send OTP. Please try again.");
    }
    setLoading(false);
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    if (otp !== generatedOtp) {
      setError("Invalid OTP. Please try again.");
      return;
    }

    setLoading(true);
    const encryptedPassword = encryptPassword(password);

    await saveUser({ email, name, password: encryptedPassword, country });
    setLoading(false);
    setShowRegister(false);
    setError("");
    setIsOtpSent(false);
    setOtp("");
    alert("User Registered Sucessfully ✅. Please log in");
  };

  const registerBiometric = async () => {
    try {
      // Check if running inside WKWebView
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.biometricAuth) {
        // Send a message to the WKWebView to register biometrics
        // alert("Wkview Register biometric triggered");
        //window.webkit.messageHandlers.biometricAuth.postMessage("register");
      } else {
        // Existing WebAuthn registration code
        const publicKey = {
          challenge: new Uint8Array(32),
          rp: { name: "Pocket Apps" },
          user: {
            id: new TextEncoder().encode(email),
            name: email,
            displayName: name,
          },
          pubKeyCredParams: [{ alg: -7, type: "public-key" }],
          authenticatorSelection: { authenticatorAttachment: "platform", userVerification: "required" },
          timeout: 60000,
          attestation: "direct",
        };
        const credential = await navigator.credentials.create({ publicKey });
        const biometricPasskey = btoa(String.fromCharCode(...new Uint8Array(credential.rawId)));
        const storedUser = await fetchUsers(email);
        await UpdateUser({ id: storedUser.id, name: storedUser.name, email, password: storedUser.password, biometricPasskey });
        localStorage.setItem("biometricEnabled", "true");
        setBiometricEnabled(true);
        alert("Face ID / Touch ID registered successfully!");
      }
    } catch (error) {
      console.error("Biometric registration failed:", error);
      setError("Failed to register Face ID / Touch ID.");
    }
  };

  const handleBiometricLogin = async () => {
    try {
      // Check if running inside WKWebView
      if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.biometricAuth) {
        // Send a message to the WKWebView to authenticate biometrics
        //alert("Wkview Log in biometric triggered");
        // window.webkit.messageHandlers.biometricAuth.postMessage("login");
      } else {
        // Existing WebAuthn login code
        const storedUser = await fetchUsers(email);
        const biometricPasskeyBuffer = Uint8Array.from(atob(storedUser.biometricPasskey), (c) => c.charCodeAt(0));
        const publicKey = {
          challenge: new Uint8Array(32),
          allowCredentials: [{ id: biometricPasskeyBuffer, type: "public-key", transports: ["internal"] }],
          timeout: 60000,
          userVerification: "required",
        };
        const assertion = await navigator.credentials.get({ publicKey });
        if (assertion) {
          onLogin({ email: storedUser.email, name: storedUser.name });
          setError("");
        }
      }
    } catch (error) {
      console.error("Biometric login failed:", error);
      setError("Failed to log in with Face ID / Touch ID.");
    }
  };
  function isWebView() {
    const userAgent = navigator.userAgent || navigator.vendor || window.opera;
    // Check for React Native WebView (window.ReactNativeWebView)
    if (window.ReactNativeWebView) {
      return true;
    }
    // Check if running in a WKWebView on iOS (older detection fallback)
    if (/iPhone|iPad|iPod/.test(userAgent) && /AppleWebKit/.test(userAgent) && !/Safari/.test(userAgent)) {
      return true;
    }
    // Check if running in Android WebView by detecting "wv" or "WebView" in user agent
    if (/wv|WebView/.test(userAgent)) {
      return true;
    }
    // Not in WebView
    return false;
  }
  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    const storedUser = await fetchUsers(email);
    setCurrentUser(storedUser);
    if (storedUser) {
      const decryptedPassword = decryptPassword(storedUser.password);
      if (decryptedPassword === password) {
        setLoading(false);
        onLogin({ email: storedUser.email, name: storedUser.name, country: storedUser.country || "" });
        setError("");
        console.log(window.webkit, "window.webki");
        if (1 == 2 && !isWebView() && !biometricEnabled && window.confirm("Do you want to enable Face ID / Touch ID for future logins?")) {
          await registerBiometric();
        }
      } else {
        setError("Invalid email or password");
        setLoading(false);
      }
    } else {
      setError("User not found. Please Register to Log in.");
      setLoading(false);
    }
  };

  return (
    <div className="">
      <header className="header bg-myapp">
        <h1 className="titlename bg-success mb-0 px-3 p-3  w-75">{config.apptitle}</h1>
        {process.env.REACT_APP_ENV === "QA" && <small className="px-2">NonProd</small>}
      </header>
      <div className="login-container px-3">
        <h3 className="login-title d-none">{showRegister ? "Register" : "Login"}</h3>
        <form onSubmit={showRegister ? (isOtpSent ? handleRegister : handleSendOtp) : handleLogin} className="login-form">
          {error && <p className="error-text text-danger">{error}</p>}
          <div align="left">Email</div>
          <input type="email" placeholder="Enter your Email" value={email} onChange={(e) => setEmail(e.target.value.toLowerCase())} required className="form-control" />
          {!showRegister && (
            <>
              <div align="left">Password</div>
              <div className="password-container" style={{ position: "relative", width: "100%" }}>
                <input type={showPassword ? "text" : "password"} placeholder="Enter your Password" value={password} onChange={(e) => setPassword(e.target.value)} required className="form-control" style={{ paddingRight: "2.5rem" }} />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="btn-eye"
                  style={{
                    position: "absolute",
                    right: "10px",
                    top: "50%",
                    transform: "translateY(-50%)",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    padding: "0",
                  }}
                >
                  {showPassword ? <FiEyeOff /> : <FiEye />}
                </button>
              </div>
            </>
          )}

          {showRegister && (
            <>
              <div align="left">Name</div>
              <input type="text" placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} required className="form-control" />
              <div align="left">Password</div>
              <div className="password-container" style={{ position: "relative", width: "100%" }}>
                <input type={showPassword ? "text" : "password"} placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required className="form-control" style={{ paddingRight: "2.5rem" }} />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="btn-eye">
                  {showPassword ? <FiEyeOff /> : <FiEye />}
                </button>
              </div>
              <div align="left">Country</div>
              <select value={country} onChange={(e) => setCountry(e.target.value)} required className="form-control mx-1">
                <option value=""></option>
                <option value="india">India</option>
                <option value="usa">USA</option>
                <option value="Other">Other</option>
              </select>
            </>
          )}
          {isOtpSent && showRegister && (
            <>
              <div align="left">Enter OTP</div>
              <input type="number" placeholder="OTP" value={otp} onChange={(e) => setOtp(e.target.value)} required className="form-control" step="any" min="0" inputMode="decimal" />
            </>
          )}

          <button type="submit" className="btn btn-lg btn-warning mt-2" disabled={loading}>
            {loading ? "Please wait..." : showRegister ? (isOtpSent ? "Register" : "Get OTP") : "Login"}
          </button>
          {!showRegister && (
            <button type="button" className="btn btn-lg bg-myapp text-dark mt-2" onClick={() => onLogin({ email: "guest", name: "guest", country: "" })}>
              Continue as Guest
            </button>
          )}

          {biometricEnabled && !showRegister && (
            <div className="d-flex justify-content-between mt-2">
              <button type="button" onClick={handleBiometricLogin} className="btn btn-md btn-warning w-75">
                <i className="fi fi-rr-fingerprint me-1"></i>
                Biometric Login
              </button>
              <button
                type="button"
                onClick={() => {
                  localStorage.removeItem("biometricEnabled");
                  setBiometricEnabled(false);
                  alert("Face ID / Touch ID cleared!");
                }}
                className="btn btn-md btn-secondary ms-2 w-25"
              >
                Clear
              </button>
            </div>
          )}
        </form>
        <div className="mt-3">
          {showRegister ? (
            <>
              Already have an account?{" "}
              <button type="button" className="toggle-link my-link" onClick={() => (setShowRegister(false), setError(""))}>
                Log in here
              </button>
            </>
          ) : (
            <>
              <div className="d-flex justify-content-between">
                <div className="mb-0" align="center">
                  <small>Forget Password?</small>
                  <button type="button" className="toggle-link my-link p-2 mt-1 text-decoration-none" onClick={() => setShowChangePassword(true)}>
                    Change Password
                  </button>{" "}
                </div>
                <div className="mx-1"> </div>
                <div className="mb-0" align="center">
                  <small> Don't have an account?</small>
                  <button type="button" className="toggle-link my-link p-2  mt-1 text-decoration-none" onClick={() => setShowRegister(true)}>
                    Register here
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
      <Modal show={showChangePassword} onHide={() => setShowChangePassword(false)} top backdrop="static" keyboard={false}>
        <div className="modal-header">
          <h5 className="modal-title">Forgot Password</h5>
          <a onClick={() => setShowChangePassword(false)}>
            <img src={close} alt="Logo" className="" width="30" />
          </a>
        </div>
        <Modal.Body>
          <ForgotPassword useremail={email} showChangePassword={showChangePassword} setShowChangePassword={setShowChangePassword} />
        </Modal.Body>
      </Modal>
      <footer className="bottom-nav rounded-top bg-myapp py-2">
        <small className="text-dark px-2">
          <a href="#" className="text-dark">
            {config.footertext}
          </a>
          <div className="d-flex">
            <a href="/public/privacypolicy" className="text-dark px-2 text-decoration-underline ">
              Privacy Policy
            </a>
            <a href="/public/contact" className="text-dark px-2 text-decoration-underline ">
              Contact us
            </a>
          </div>
        </small>
      </footer>
    </div>
  );
};

export default LoginPage;
