const MainApp = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoggedOut, setIsLoggedOut] = useState(JSON.parse(localStorage.getItem("isLoggedOut")));
  const [showRegister, setShowRegister] = useState(false);
  const [alertVisible, setAlertVisible] = useState(false);
  const [isAdminVisible, setIsAdminVisible] = useState(true);
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState(null); // Store the prompt event
  const [showA2HSButton, setShowA2HSButton] = useState(false); // Show button when prompt is available

  const matchApp1 = useMatch("/app1/*");
  const matchApp2 = useMatch("/app2/*");
  const matchApp31 = useMatch("/app3/*");
  const matchApp5 = useMatch("/app5/*");
  const matchApp6 = useMatch("/app6/*"); //finalcial calc
  const _App4 = useMatch("/app4/*");
  const _admin = useMatch("/admin/*");
  const matchApp3 = useMatch("/manage/*");
  const matchApp4 = useMatch("/public/*");

  //console.log("matchApp4", matchApp4);
  const navigate = useNavigate();
  useEffect(() => {
    // Listen for the beforeinstallprompt event
    const handleBeforeInstallPrompt = (event) => {
      event.preventDefault(); // Prevents the default mini-infobar from appearing on mobile
      setDeferredPrompt(event); // Store the event for triggering later
      setShowA2HSButton(true); // Show the A2HS button
    };
    setIsLoggedOut(JSON.parse(localStorage.getItem("isLoggedOut")));
    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
    };
    const sessionUser = JSON.parse(localStorage.getItem("loggedInUser"));
    if (sessionUser) {
      setEmail(sessionUser.email);
    }
  }, []);

  const handleAddToHomeScreen = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt(); // Show the A2HS prompt
      deferredPrompt.userChoice.then((choiceResult) => {
        if (choiceResult.outcome === "accepted") {
          console.log("User accepted the A2HS prompt");
        } else {
          console.log("User dismissed the A2HS prompt");
        }
        setDeferredPrompt(null);
        setShowA2HSButton(false); // Hide the button after prompt
      });
    }
  };

  useEffect(() => {
    const sessionUser = JSON.parse(localStorage.getItem("loggedInUser"));
    const guestUser = JSON.parse(localStorage.getItem("guestUser"));

    if (sessionUser) {
      setIsLoggedIn(true);
      setEmail(sessionUser.email);
      setName(sessionUser.name);
    } else if (guestUser) {
      setIsLoggedIn(true);
      setEmail("guest");
      setName("guest");
    } else {
      setIsLoggedIn(false);
    }
  }, [isLoggedIn, navigate]);

  const isNestedApp = matchApp1 || matchApp31 || matchApp2 || matchApp3 || matchApp4 || _App4 || _admin || matchApp5 || matchApp6;

  const handleLogin = (userData) => {
    if (userData.email === "guest") {
      localStorage.setItem("guestUser", JSON.stringify(userData));
      localStorage.setItem("isLoggedOut", false);
      localStorage.setItem("loggedInUserEmail", "guest");
    } else {
      localStorage.setItem("loggedInUser", JSON.stringify(userData));
      localStorage.setItem("loggedInUserEmail", userData.email);
      localStorage.setItem("isLoggedOut", false);
    }
    setIsLoggedOut(false);
    setIsLoggedIn(userData);
  };

  if ((!isLoggedIn || isLoggedOut) && !matchApp4) {
    return (
      <div>
        <div className="container mb-0 d-flex flex-column align-items-center">
          <div>
            <p className="mb-0">Welcome to {config.apptitle}</p>
          </div>
          <div>
            {" "}
            <p align="center" className="app-description">
              {config.appdescription}
              {/* <button onclick="window.webkit.messageHandlers.biometricAuth.postMessage('register');">Test Biometric</button> */}
            </p>
          </div>
        </div>
        <div style={styles1.container} className="p-2 d-none">
          <div style={styles1.iconContainer}>
            <a href="#" style={styles1.appIconLink}>
              <img src={image} alt="Expense Tracker" style={styles1.appIcon} />
              <p style={styles1.appText} className="mb-0">
                Expense Tracker
              </p>
            </a>
          </div>
          <div style={styles1.iconContainer}>
            <a href="#" style={styles1.appIconLink}>
              <img src={icon1} alt="Split Equal" style={styles1.appIcon} />
              <p style={styles1.appText} className="mb-0">
                Split Equal
              </p>
            </a>
          </div>
          <div style={styles1.iconContainer} className="d-none">
            <a href="#" style={styles1.appIconLink}>
              <img src={qr} alt="QR Generator" style={styles1.appIcon} />
              <p style={styles1.appText} className="mb-0">
                QR Generator
              </p>
            </a>
          </div>
          <div style={styles1.iconContainer} className="">
            <a href="#" style={styles1.appIconLink}>
              <img src={todo} alt="ToDo" style={styles1.appIcon} />
              <p style={styles1.appText} className="mb-0">
                ToDo
              </p>
            </a>
          </div>
        </div>
        <AppCarousel />
        <LoginPage onLogin={handleLogin} />
        <div className="container mt-0 d-flex flex-column align-items-center">
          {/* <div>
            <small>Welcome to {config.apptitle}</small>
          </div> */}
          <div>
            <img src={banner} height="150" alt="Login Banner" />
          </div>
          <p align="center" className="app-description px-2">
            {config.appdescription2}
          </p>
        </div>
      </div>
    );
  }
  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text).then(
      () => {
        setAlertVisible(true);
        setTimeout(() => setAlertVisible(false), 1000);
      },
      (err) => {
        console.error("Failed to copy text:", err);
      }
    );
  };
  const NotFoundPage = () => {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        <h1>404 - Page Not Found</h1>
        <p>The page you are looking for does not exist.</p>
        <button onClick={() => (window.location.href = "/")} style={{ padding: "10px 20px", fontSize: "16px" }}>
          Go to Home
        </button>
      </div>
    );
  };
  return (
    <div>
      {!isNestedApp && (
        <div>
          <header className="header bg-myapp">
            <h1 className="titlename bg-success mb-0 px-3 p-3  w-75">{config.apptitle}</h1>
            {process.env.REACT_APP_ENV === "QA" && <small className="px-2">NonProd</small>}
            <span to="/" className="p-3 d-none">
              <a href="/manage/profile" className="">
                <img src={user} alt="user" width="20" />
              </a>
            </span>
          </header>
          <div className="mt-5 py-2"></div>
          <div align="right">
            <p className="mb-0 p-2">
              <small>Welcome, {name}!</small>
            </p>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "10px", padding: "10px" }}>
            {apps.map((app, index) => (
              <div key={index} className={app.display ? "" : "d-none"} style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                <a href={app.href} style={{ textDecoration: "none", textAlign: "center" }}>
                  <img src={app.image} alt={app.name} style={{ width: "75px", height: "75px", borderRadius: "15px", boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.2)" }} />
                  <p style={{ marginTop: "8px", fontSize: "12px", color: "#000" }}>{app.name}</p>
                </a>
              </div>
            ))}
          </div>
          {/* Admin Link */}{" "}
          {isAdminVisible && email === "vbalakumar.cse@gmail.com" && (
            <div style={styles.container}>
              <div style={styles.iconContainer} className="">
                <button
                  className="btn btn-small bg-danger border p-0 px-1"
                  style={styles.closeButton}
                  onClick={() => setIsAdminVisible(false)} // Hide the icon on click
                  aria-label="Close"
                >
                  Close
                </button>
                <a href="/admin/dashboard" style={styles.appIconLink}>
                  <img src={admin} alt="admin" style={styles.appIcon} />
                  <p style={styles.appText} className="mb-0">
                    Admin
                  </p>
                </a>
              </div>
            </div>
          )}
          <div className="container">
            <span>
              <button className="share-button" onClick={() => copyToClipboard(config.iosurl)}>
                <i className="fa fa-apple"></i>
              </button>
            </span>
            <span>
              <button className="share-button" style={{ bottom: "145px" }} onClick={() => copyToClipboard(config.androidurl)}>
                <i className="fa fa-android"></i>
              </button>
            </span>
            <small className="share-text ">
              <i className="fa fa-share text-secondary"></i>
            </small>
          </div>
          <div align="center" className="home-footer-text">
            <p className="mb-0">
              <small>All in One Pocket Apps Hub</small>
            </p>
            <small>for your Daily Needs!!</small>
          </div>
          <BottomNav />
        </div>
      )}
      <ErrorBoundary>
        <Routes>
          <Route path="/app1/*" element={<App1 />} />
          <Route path="/app2/*" element={<App2 />} />
          <Route path="/app3/*" element={<App3 />} />
          <Route path="/app4/*" element={<App4 />} />
          <Route path="/app5/*" element={<App5 />} />
          <Route path="/app6/*" element={<App6 />} />
          <Route path="/manage/*" element={<AppManage />} />
          <Route path="/admin/*" element={<Admin />} />
          <Route path="/public/*" element={<AppPublic />} />
          {/* <Route path="/*" element={<NotFoundPage />} /> */}
        </Routes>
      </ErrorBoundary>
      {/* Add to Home Screen button at the bottom */}
      {showA2HSButton && (
        <button onClick={handleAddToHomeScreen} className="btn btn-sm btn-warning w-auto px-2 p-1 text-dark shadow border d-none" style={styles.a2hsButton}>
          <small className="text-nowrap">Add to Home Screen as App</small>
        </button>
      )}
      <div className="d-flex justify-content-end align-items-center mb-0 m-1">
        {alertVisible && (
          <div className="d-flex justify-content-center text-dark w-100">
            <div
              className="bg-white border justify-content-center text-dark "
              style={{
                color: "white",
                padding: "5px",
                borderRadius: "5px",

                zIndex: 1000,
              }}
            >
              Link copied to clipboard for Sharing
            </div>
          </div>
        )}
      </div>
      {/* Temporary Alert */}
    </div>
  );
};

