import React, { useState, useEffect } from "react";
import { getDataFromServer } from "../service/APIService";

const ExpenseList = () => {
  const [friends, setFriends] = useState([]);
  const [expenses, setExpenses] = useState([]);
  const [loggedInUser, setLoggedInUser] = useState(null);
  const [sessionInitialized, setSessionInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [visibleExpenses, setVisibleExpenses] = useState(10); // Initial number of visible expenses
  const [searchTerm, setSearchTerm] = useState("");
  const loggedInUserEmail = localStorage.getItem("loggedInUserEmail");
  useEffect(() => {
    const initializeUserSession = async () => {
      const sessionUser = JSON.parse(localStorage.getItem("loggedInUser"));
      if (sessionUser && loggedInUserEmail !== "guest") {
        setLoggedInUser(sessionUser.email);
        setSessionInitialized(true);
      }
    };
    initializeUserSession();
  }, []);

  useEffect(() => {
    if (sessionInitialized && loggedInUser) {
      const fetchUserData = async () => {
        try {
          setLoading(true);
          const users = await getDataFromServer(loggedInUser);
          const user = users.find((user) => user.email === loggedInUser);
          if (user) {
            setFriends(user.friends || []);
            setExpenses(user.expenses || []);
          }
        } catch (error) {
          console.error("Error fetching user data:", error);
        } finally {
          setLoading(false);
        }
      };
      fetchUserData();
    }
  }, [sessionInitialized, loggedInUser]);

  // Filter and sort the expenses
  const filteredExpenses = expenses.filter((expense) => expense.description.toLowerCase().includes(searchTerm.toLowerCase()) || expense.friend.toLowerCase().includes(searchTerm.toLowerCase())).sort((a, b) => new Date(b.date) - new Date(a.date));

  // Handle "Load More" button click
  const loadMoreExpenses = () => {
    setVisibleExpenses((prevVisible) => prevVisible + 5); // Load 5 more expenses on each click
  };

  return (
    <div className="container">
      {/* Search Input */}
      <div className="mb-3 mt-2">
        <input type="text" className="form-control" placeholder="Search expenses" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      </div>

      {/* Expense List */}
      {loading ? (
        <p className="p-2 border rounded">
          <span className="px-1">
            <i className="fas fa-spinner fa-spin text-success"></i>
          </span>
          Loading data... Please wait.
        </p>
      ) : (
        <div>
          <ul className="list-unstyled p-1">
            {expenses.length === 0
              ? "No Expense History found."
              : filteredExpenses.slice(0, visibleExpenses).map((expense, index) => (
                  <li key={index} className="d-flex justify-content-between align-items-center border rounded mt-1 p-1 compact-list-item">
                    <div>
                      <strong className="d-block">
                        <small>{expense.description}</small> -<small className="text-muted">{new Date(expense.date).toLocaleDateString()}</small>
                      </strong>
                      <p className="text-muted mb-0">{expense.type === "split" ? `You and ${expense.friend} split this equally.` : expense.type === "you-paid-full" ? `You paid the full amount. ${expense.friend} owes you $${expense.amount.toFixed(2)}.` : expense.type === "friend-paid-full" ? `${expense.friend} paid the full amount. You owe ${expense.friend} $${expense.amount.toFixed(2)}.` : expense.type === "friend-paid-split" ? `${expense.friend} paid and you owe half.` : expense.type === "settle" ? `Settle Up: You settled $${expense.amount.toFixed(2)} with ${expense.friend}.` : ""}</p>
                    </div>
                    <div>
                      <span className={`badge ${expense.type === "friend-owes" || expense.type === "settle" || expense.type === "you-paid-full" ? "bg-success" : "bg-danger"}`}>${expense.amount.toFixed(2)}</span>
                    </div>
                  </li>
                ))}
          </ul>
          {/* Load More Button */}
          {visibleExpenses < filteredExpenses.length && (
            <div className="d-flex justify-content-center m-2 mb-5 py-4">
              <button className="btn btn-sm btn-warning mb-4" onClick={loadMoreExpenses}>
                Load More
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ExpenseList;
